"""Bilingual configuration lifecycle page; no credentials or raw backups in browser storage."""
CONFIG_PAGE = r'''<!doctype html>
<html lang="zh"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Configuration & Drift</title><style>
:root{color-scheme:dark;--bg:#0b1220;--card:#141f31;--line:#33435d;--muted:#a5b5cc;--text:#edf3fd;--blue:#74b7ff;--green:#67dbba;--red:#ff9b9b}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.55 system-ui,sans-serif}main{max-width:1440px;margin:auto;padding:30px 24px 70px}header,.bar,.actions,.split{display:flex;gap:16px;align-items:center;justify-content:space-between;flex-wrap:wrap}h1{font-size:30px;margin:4px 0}h2{font-size:20px;margin:0 0 16px}h3{font-size:16px;margin:4px 0 12px}p{margin:8px 0}.muted,small{color:var(--muted)}.pill{display:inline-block;padding:3px 10px;border:1px solid var(--line);border-radius:20px;color:var(--green);font-size:12px}.card{background:var(--card);border:1px solid var(--line);border-radius:12px;margin-top:22px;padding:24px;box-shadow:0 8px 30px #0002}.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}.field{display:flex;flex-direction:column;gap:6px;min-width:150px}label{font-size:14px}input,select,button{font:inherit;border-radius:6px;border:1px solid #496080;padding:8px 11px;color:var(--text);background:#0c1728;max-width:100%}input[type=checkbox]{accent-color:var(--blue);width:17px;height:17px}button{cursor:pointer;background:#263d5b}button.primary{background:#2370ba;border-color:#3992e7}button.danger{background:#8b343e}button:disabled{opacity:.45;cursor:not-allowed}button:hover:enabled{filter:brightness(1.2)}a{color:var(--blue)}.actions{justify-content:flex-start;gap:10px;margin:14px 0}.devices{display:grid;grid-template-columns:repeat(auto-fit,minmax(175px,1fr));gap:8px}.device{display:flex;align-items:center;gap:9px;padding:9px;border:1px solid var(--line);border-radius:6px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap}th,td{text-align:left;padding:10px 12px;border-bottom:1px solid var(--line);font-size:13px}th{color:var(--muted)}td button{font-size:12px;padding:4px 10px;margin-right:5px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;background:#0a1525;border-radius:6px;padding:14px;max-height:360px;overflow:auto;margin:8px 0}.diff{border:1px solid var(--line);border-radius:8px;padding:16px;margin:12px 0}.before{border-left:3px solid #da7b86}.after{border-left:3px solid #67dbba}.notice{border-left:3px solid var(--blue);background:#19324e;padding:12px 16px;margin:12px 0}.error{border-color:var(--red);background:#41242b}.success{color:var(--green)}#message{position:sticky;top:8px;z-index:10;white-space:pre-wrap}.busy{opacity:.65;pointer-events:none}.audit-detail{white-space:normal;max-width:620px}details summary{cursor:pointer}.toolbar{display:flex;gap:12px;align-items:end;flex-wrap:wrap}.toolbar .field{flex:1}hr{border:0;border-top:1px solid var(--line);margin:20px 0}[hidden]{display:none!important}@media(max-width:800px){.grid{grid-template-columns:1fr}main{padding:18px 12px}.card{padding:17px}h1{font-size:24px}.toolbar .field{min-width:180px}}
</style></head><body><main>
<header><div><span class="pill">Q3 · Configuration & Drift</span><h1 data-i="title"></h1><p class="muted" data-i="intro"></p></div><div class="field"><label for="lang">语言 / Language</label><select id="lang"><option value="zh">中文</option><option value="en">English</option></select></div></header>
<div id="message" role="status" hidden></div>
<section class="card"><div class="bar"><h2 data-i="backupTitle"></h2><span class="pill" data-i="scope"></span></div>
<div class="toolbar"><div class="field"><label for="actor" data-i="actor"></label><input id="actor" maxlength="100" autocomplete="name" placeholder="operator"></div></div>
<div class="actions"><button id="all" data-i="all"></button><button id="none" data-i="none"></button><span id="selectionCount" class="muted"></span></div><div id="devices" class="devices"></div>
<div class="actions"><button id="backup" class="primary" data-i="backupNow"></button><span class="muted" data-i="backupHint"></span></div>
<hr><h3 data-i="scheduleTitle"></h3><div class="toolbar"><label><input id="enabled" type="checkbox"> <span data-i="enabled"></span></label><div class="field"><label for="dailyTime" data-i="dailyTime"></label><input id="dailyTime" type="time" required></div><div class="field"><label for="timezone" data-i="timezone"></label><input id="timezone" list="zones" value="Asia/Shanghai"><datalist id="zones"><option value="Asia/Shanghai"><option value="UTC"><option value="Asia/Hong_Kong"></datalist></div></div>
<div class="actions"><label><input id="scheduleAll" type="checkbox" checked> <span data-i="scheduleAll"></span></label><button id="saveSchedule" data-i="saveSchedule"></button></div><p id="scheduleSummary" class="muted"></p></section>
<section class="card"><h2 data-i="historyTitle"></h2><div class="toolbar"><div class="field"><label for="historyDevice" data-i="device"></label><select id="historyDevice"></select></div><div class="field"><label for="rangeStart" data-i="rangeStart"></label><input id="rangeStart" type="datetime-local" step="1"></div><div class="field"><label for="rangeEnd" data-i="rangeEnd"></label><input id="rangeEnd" type="datetime-local" step="1"></div><button id="loadHistory" data-i="filter"></button></div>
<p class="muted" data-i="historyHint"></p><div class="scroll"><table><thead><tr><th data-i="observed"></th><th data-i="status"></th><th data-i="source"></th><th data-i="version"></th><th data-i="choose"></th></tr></thead><tbody id="historyRows"></tbody></table></div>
<div class="actions"><button id="previous" data-i="previous"></button><span id="historyCount"></span><button id="next" data-i="next"></button></div>
<hr><h3 data-i="compareTitle"></h3><div class="toolbar"><div class="field"><label for="beforeTime" data-i="beforeTime"></label><input id="beforeTime" type="datetime-local" step="0.001"></div><div class="field"><label for="afterTime" data-i="afterTime"></label><input id="afterTime" type="datetime-local" step="0.001"></div><button id="compare" class="primary" data-i="compare"></button></div><p class="muted" data-i="timeHint"></p><div id="comparison"></div></section>
<section class="card"><h2 data-i="restoreTitle"></h2><p class="notice" data-i="restoreHint"></p><div class="toolbar"><div class="field"><label for="targetVersion" data-i="targetVersion"></label><select id="targetVersion"></select></div><div class="field"><label for="changeRef" data-i="changeRef"></label><input id="changeRef" maxlength="100"></div><button id="preview" data-i="preview"></button></div><div id="restorePreview"></div>
<div id="execution" hidden><div class="notice" data-i="confirmHint"></div><div class="toolbar"><div class="field"><label for="confirmDevice" data-i="confirmDevice"></label><input id="confirmDevice" autocomplete="off"></div><div class="field"><label for="restoreToken" data-i="restoreToken"></label><input id="restoreToken" type="password" autocomplete="off"></div><button id="execute" class="danger" data-i="execute"></button></div><p class="muted" data-i="tokenHint"></p></div></section>
<section class="card"><div class="bar"><h2 data-i="auditTitle"></h2><button id="refreshAudit" data-i="refresh"></button></div><p class="muted" data-i="auditHint"></p><div class="scroll"><table><thead><tr><th data-i="observed"></th><th data-i="action"></th><th data-i="actor"></th><th data-i="status"></th><th data-i="details"></th></tr></thead><tbody id="auditRows"></tbody></table></div><div class="actions"><button id="auditPrevious" data-i="previous"></button><span id="auditCount"></span><button id="auditNext" data-i="next"></button></div></section>
</main><script>
const words={zh:{title:'配置管理与漂移',intro:'按计划备份 · 历史配置比对 · 恢复预览与审计',backupTitle:'01 / 设备备份与每日计划',scope:'当前范围：Nautobot lab',actor:'操作人',all:'全选',none:'清空',backupNow:'立即备份所选设备',backupHint:'每次成功备份均保留时间记录，相同配置共用一个版本。',scheduleTitle:'每日自动备份',enabled:'启用每日备份',dailyTime:'执行时间',timezone:'时区（IANA）',scheduleAll:'每天备份所有当前 lab 设备；取消勾选则使用上方所选设备',saveSchedule:'保存每日计划',historyTitle:'02 / 历史记录与时间比对',device:'设备',rangeStart:'历史起始时间',rangeEnd:'历史结束时间',filter:'查询历史',historyHint:'时间按浏览器本地时区显示。历史升级前仅保留已有证据的采样时间；失败记录不能用于比对。',observed:'时间',status:'结果',source:'来源',version:'配置版本',choose:'选择',useRestore:'选作恢复目标',previous:'上一页',next:'下一页',compareTitle:'双时间配置比对',beforeTime:'A · 起始时间',afterTime:'B · 结束时间',compare:'比较 A → B',timeHint:'匹配所选时间当时或之前最近一次成功备份；结果明确列出实际采样时间。',restoreTitle:'03 / 恢复预览与执行',restoreHint:'可预览 lab 设备的恢复差异。执行试点仅开放 p1-host（EOS）；恢复运行配置，启动配置另行管理。',targetVersion:'恢复目标版本（当前所选设备）',changeRef:'变更编号 / 原因引用',preview:'读取当前配置并预览',confirmHint:'执行前自动备份当前配置。预览有效期 10 分钟；配置变化后必须重新预览。EOS 提交使用 5 分钟确认倒计时，验证失败时须检查回退状态。',confirmDevice:'输入完整设备名称确认',restoreToken:'恢复操作密钥',execute:'执行恢复并验证',tokenHint:'恢复密钥由服务器管理员提供；页面不会保存密钥。',auditTitle:'04 / 操作审计',refresh:'刷新',auditHint:'记录备份、计划修改、恢复预览及执行结果。操作人由用户填写，变更引用不等同于外部审批。',action:'操作',details:'详情',selected:'已选设备',nextRun:'下次执行',disabled:'已停用',saved:'新版本',unchanged:'配置未变化',error:'失败',manual:'手动备份',daily:'每日计划',legacy:'历史迁移',restore_preview:'恢复预览',pre_restore:'恢复前备份',post_restore:'恢复后备份',backup:'配置备份',schedule:'每日计划',restore_execute:'恢复执行',running:'执行中',ok:'成功',partial:'部分失败',busy:'已有任务执行中',verification_required:'需核查恢复状态',restored:'恢复完成',noData:'没有记录',noDiff:'两个配置一致，没有差异。',before:'之前',after:'之后',matched:'实际比对采样时间',ready:'预览完成',expires:'预览到期',previewOnly:'此设备目前仅支持恢复预览。',required:'请填写操作人及必要的选择项。',working:'正在执行，请稍候…',done:'操作完成',count:'记录',noSelection:'请先选择至少一台设备。',confirm:'将恢复设备运行配置，是否执行？',modified:'修改',added:'新增',removed:'删除'},en:{title:'Configuration & Drift',intro:'Scheduled backups · Historical comparison · Recovery preview & audit',backupTitle:'01 / Device backups & daily schedule',scope:'Scope: current Nautobot lab',actor:'Operator',all:'Select all',none:'Clear',backupNow:'Back up selected devices',backupHint:'Every successful backup keeps an observation time; unchanged configurations share one version.',scheduleTitle:'Daily automatic backup',enabled:'Enable daily backup',dailyTime:'Run at',timezone:'Timezone (IANA)',scheduleAll:'Back up all current lab devices daily; uncheck to use the selection above',saveSchedule:'Save daily schedule',historyTitle:'02 / History & time comparison',device:'Device',rangeStart:'History start',rangeEnd:'History end',filter:'Load history',historyHint:'Times use your browser timezone. Legacy history contains only known observation times. Failed backups cannot be compared.',observed:'Time',status:'Result',source:'Source',version:'Version',choose:'Select',useRestore:'Use for recovery',previous:'Previous',next:'Next',compareTitle:'Compare two times',beforeTime:'A · Before',afterTime:'B · After',compare:'Compare A → B',timeHint:'Uses the latest successful backup at or before each selected time. Actual observation times are shown.',restoreTitle:'03 / Recovery preview & execution',restoreHint:'Preview recovery for lab devices. Execution pilot: p1-host (EOS) only. Restores running configuration; startup configuration is managed separately.',targetVersion:'Target backup version (selected device)',changeRef:'Change reference',preview:'Read current config & preview',confirmHint:'A safety backup is taken before recovery. Preview expires after 10 minutes and becomes invalid if configuration changes. EOS uses a 5-minute commit-confirm timer; inspect rollback state if verification fails.',confirmDevice:'Type the full device name',restoreToken:'Recovery operator token',execute:'Restore & verify',tokenHint:'Obtain the recovery token from the server administrator. This page never stores it.',auditTitle:'04 / Operation audit',refresh:'Refresh',auditHint:'Records backups, schedule updates, previews and recovery outcomes. Operator names are user supplied; change references do not prove external approval.',action:'Action',details:'Details',selected:'Selected devices',nextRun:'Next run',disabled:'Disabled',saved:'New version',unchanged:'Unchanged',error:'Failed',manual:'Manual',daily:'Daily schedule',legacy:'Legacy evidence',restore_preview:'Recovery preview',pre_restore:'Pre-recovery backup',post_restore:'Post-recovery backup',backup:'Backup',schedule:'Daily schedule',restore_execute:'Recovery execution',running:'Running',ok:'Successful',partial:'Partial failure',busy:'Operation already running',verification_required:'Inspect recovery state',restored:'Restored',noData:'No records',noDiff:'Configurations match. No differences.',before:'Before',after:'After',matched:'Actual observation times',ready:'Preview ready',expires:'Expires',previewOnly:'This device currently supports preview only.',required:'Enter an operator and complete the required selections.',working:'Working, please wait…',done:'Operation complete',count:'records',noSelection:'Select at least one device.',confirm:'Restore the device running configuration now?',modified:'Modified',added:'Added',removed:'Removed'}};
const $=id=>document.getElementById(id);let lang=new URLSearchParams(location.search).get('lang')==='en'?'en':'zh';let devices=[],rows=[],versions=[],schedule={},plan=null,historyOffset=0,auditOffset=0,historyTotal=0,auditData={records:[],total:0},exactTimes={},lastComparison=null;const pageSize=50;
const t=k=>words[lang][k]||k,fmt=s=>s?new Date(s*1000).toLocaleString(lang==='zh'?'zh-CN':'en-GB',{hour12:false}):'—';
function node(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}
function notify(text,error=false){const e=$('message');e.hidden=false;e.className='notice'+(error?' error':'');e.textContent=text}
async function api(path,method='GET',body,token){const headers={'Content-Type':'application/json'};if(token)headers['X-Config-Restore-Token']=token;const r=await fetch('/config'+path,{method,headers,body:body===undefined?undefined:JSON.stringify(body)});let v=await r.json();if(!r.ok)throw Error(typeof v.detail==='string'?v.detail:JSON.stringify(v.detail));return v}
async function task(fn){document.querySelector('main').classList.add('busy');notify(t('working'));try{await fn();notify(t('done'))}catch(e){notify(e.message,true)}finally{document.querySelector('main').classList.remove('busy')}}
function actor(){const v=$('actor').value.trim();if(!v)throw Error(t('required'));return v}
function chosen(){return [...document.querySelectorAll('#devices input:checked')].map(e=>e.value)}
function countSelection(){$('selectionCount').textContent=t('selected')+': '+chosen().length+' / '+devices.length;$('backup').disabled=!chosen().length}
function localTime(stamp){const d=new Date(stamp*1000);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,23)}
function setTime(which,stamp){$(which).value=localTime(stamp);exactTimes[which]=stamp}
function selectedTime(which){if(!$(which).value)throw Error(t('required'));return exactTimes[which]??(new Date($(which).value).getTime()/1000+.000999)}
function resetPreview(){plan=null;$('restorePreview').replaceChildren();$('execution').hidden=true;$('confirmDevice').value='';$('restoreToken').value=''}
function renderSchedule(){let names=schedule.devices?.length?schedule.devices.map(id=>devices.find(d=>d.id===id)?.name||id).join(', '):t('all');$('scheduleSummary').textContent=(schedule.enabled?t('nextRun')+': '+new Date(schedule.next_run_at).toLocaleString()+' · '+schedule.time+' '+schedule.timezone:t('disabled'))+' · '+names}
function renderHistory(){const body=$('historyRows');body.replaceChildren();for(const row of rows){const tr=node('tr');for(const value of [fmt(row.observed_at),t(row.status),t(row.source),row.version_id?.slice(0,12)||'—'])tr.append(node('td',value));const actions=node('td');if(row.version_id){for(const [label,which] of [['A','beforeTime'],['B','afterTime']]){const b=node('button',label);b.onclick=()=>setTime(which,row.observed_at);actions.append(b)}const b=node('button',t('useRestore'));b.onclick=()=>{$('targetVersion').value=row.version_id;resetPreview();$('targetVersion').scrollIntoView({behavior:'smooth',block:'center'})};actions.append(b)}else actions.textContent=row.error||'—';tr.append(actions);body.append(tr)}if(!rows.length){const tr=node('tr');const td=node('td',t('noData'));td.colSpan=5;tr.append(td);body.append(tr)}$('historyCount').textContent=(rows.length?historyOffset+1:0)+'–'+(historyOffset+rows.length)+' / '+historyTotal+' '+t('count');$('previous').disabled=historyOffset===0;$('next').disabled=historyOffset+rows.length>=historyTotal}
function configText(value){if(value===null||value===undefined)return '—';if(Array.isArray(value))return value.map(r=>typeof r==='string'?r:('   '.repeat((r.path||[]).length)+(r.command||JSON.stringify(r)))).join('\n');return JSON.stringify(value,null,2)}
function renderDiff(target,changes){if(!changes.length){target.append(node('p',t('noDiff'),'success'));return}for(const change of changes){const card=node('div',undefined,'diff');card.append(node('h3',change.context+' · '+t(change.operation)));const grid=node('div',undefined,'grid');for(const side of ['before','after']){const col=node('div');col.append(node('small',t(side)));col.append(node('pre',configText(change[side]),side));grid.append(col)}card.append(grid);target.append(card)}}
function showComparison(){const box=$('comparison');box.replaceChildren();if(!lastComparison)return;box.append(node('p',t('matched')+': '+fmt(lastComparison.before.observed_at)+' → '+fmt(lastComparison.after.observed_at),'notice'));renderDiff(box,lastComparison.changes)}
function showPlan(){const box=$('restorePreview');box.replaceChildren();if(!plan)return;box.append(node('p',t('ready')+' · '+plan.device+' · '+t('expires')+': '+fmt(plan.expires_at),'notice'));renderDiff(box,plan.changes);$('execution').hidden=!plan.execution_supported;if(!plan.execution_supported)box.append(node('p',t('previewOnly'),'muted'))}
function renderAudit(){const body=$('auditRows');body.replaceChildren();for(const r of auditData.records){const tr=node('tr');for(const v of [fmt(r.created_at),t(r.action),r.actor,t(r.status)])tr.append(node('td',v));const td=node('td',undefined,'audit-detail'),details=node('details');details.append(node('summary',t('details')));details.append(node('pre',JSON.stringify(r.details,null,2)));td.append(details);tr.append(td);body.append(tr)}$('auditCount').textContent=(auditData.records.length?auditOffset+1:0)+'–'+(auditOffset+auditData.records.length)+' / '+auditData.total+' '+t('count');$('auditPrevious').disabled=auditOffset===0;$('auditNext').disabled=auditOffset+auditData.records.length>=auditData.total}
function translate(){document.documentElement.lang=lang;document.querySelectorAll('[data-i]').forEach(e=>e.textContent=t(e.dataset.i));$('lang').value=lang;countSelection();renderSchedule();renderHistory();renderAudit();showComparison();showPlan()}
async function loadAudit(){auditData=await api('/audit?limit='+pageSize+'&offset='+auditOffset);renderAudit()}
async function loadHistory(reset=false){if(reset)historyOffset=0;const id=$('historyDevice').value;if(!id)return;const params=new URLSearchParams({device_id:id,limit:pageSize,offset:historyOffset});if($('rangeStart').value)params.set('start',new Date($('rangeStart').value).getTime()/1000);if($('rangeEnd').value)params.set('end',new Date($('rangeEnd').value).getTime()/1000+.999999);const data=await api('/history?'+params);rows=data.records;historyTotal=data.total;renderHistory()}
async function loadVersions(){const data=await api('/backups?device_id='+encodeURIComponent($('historyDevice').value)+'&limit=1000');versions=data.versions;const el=$('targetVersion');el.replaceChildren();for(const v of versions){const opt=node('option',fmt(v.created_at)+' · '+v.id.slice(0,12));opt.value=v.id;el.append(opt)}$('preview').disabled=!versions.length}
async function deviceChanged(){resetPreview();lastComparison=null;showComparison();exactTimes={};$('beforeTime').value='';$('afterTime').value='';await Promise.all([loadHistory(true),loadVersions()]);const good=rows.filter(r=>r.version_id);if(good.length){setTime('afterTime',good[0].observed_at);setTime('beforeTime',(good[1]||good[0]).observed_at)}}
$('lang').onchange=()=>{lang=$('lang').value;const u=new URL(location);u.searchParams.set('lang',lang);history.replaceState(null,'',u);translate()};
$('all').onclick=()=>{document.querySelectorAll('#devices input').forEach(e=>e.checked=true);countSelection()};$('none').onclick=()=>{document.querySelectorAll('#devices input').forEach(e=>e.checked=false);countSelection()};
$('backup').onclick=()=>task(async()=>{const ids=chosen();if(!ids.length)throw Error(t('noSelection'));const result=await api('/backup','POST',{devices:ids,actor:actor()});await Promise.all([loadHistory(true),loadVersions(),loadAudit()]);if(result.status!=='ok')throw Error(t(result.status)+' · '+result.devices.filter(d=>d.status==='error').map(d=>d.device).join(', '))});
$('saveSchedule').onclick=()=>task(async()=>{const ids=$('scheduleAll').checked?[]:chosen();if(!$('scheduleAll').checked&&!ids.length)throw Error(t('noSelection'));schedule=await api('/schedule','PUT',{enabled:$('enabled').checked,time:$('dailyTime').value,timezone:$('timezone').value.trim(),devices:ids,actor:actor()});renderSchedule();await loadAudit()});
$('historyDevice').onchange=()=>task(deviceChanged);$('loadHistory').onclick=()=>task(()=>loadHistory(true));$('previous').onclick=()=>task(async()=>{historyOffset=Math.max(0,historyOffset-pageSize);await loadHistory()});$('next').onclick=()=>task(async()=>{historyOffset+=pageSize;await loadHistory()});
for(const id of ['beforeTime','afterTime'])$(id).oninput=()=>delete exactTimes[id];
$('compare').onclick=()=>task(async()=>{lastComparison=await api('/compare?'+new URLSearchParams({device_id:$('historyDevice').value,before_at:selectedTime('beforeTime'),after_at:selectedTime('afterTime')}));showComparison()});
for(const id of ['targetVersion','changeRef','actor'])$(id).addEventListener('input',resetPreview);
$('preview').onclick=()=>task(async()=>{resetPreview();const ref=$('changeRef').value.trim();if(!ref||!$('targetVersion').value)throw Error(t('required'));plan=await api('/restore/preview','POST',{device:$('historyDevice').value,version_id:$('targetVersion').value,actor:actor(),change_ref:ref});showPlan();await loadAudit()});
$('execute').onclick=()=>{if(!confirm(t('confirm')))return;task(async()=>{if(!plan||!$('restoreToken').value||!$('confirmDevice').value)throw Error(t('required'));let result;try{result=await api('/restore/execute','POST',{preview_id:plan.id,confirm_device:$('confirmDevice').value},$('restoreToken').value)}finally{$('restoreToken').value='';await loadAudit()}resetPreview();$('restorePreview').append(node('p',t(result.status)+' · '+result.device+' · '+result.restored_version_id.slice(0,12),'notice'));await Promise.all([loadHistory(true),loadVersions()])})};
$('refreshAudit').onclick=()=>task(async()=>{auditOffset=0;await loadAudit()});$('auditPrevious').onclick=()=>task(async()=>{auditOffset=Math.max(0,auditOffset-pageSize);await loadAudit()});$('auditNext').onclick=()=>task(async()=>{auditOffset+=pageSize;await loadAudit()});
translate();task(async()=>{const data=await api('/devices');devices=data.devices;for(const d of devices){const label=node('label',undefined,'device'),check=node('input');check.type='checkbox';check.value=d.id;check.checked=true;check.onchange=countSelection;label.append(check,node('span',d.name));$('devices').append(label);const opt=node('option',d.name+' · '+d.platform.replace('arista_','').replace('paloalto_',''));opt.value=d.id;$('historyDevice').append(opt)}const pilot=devices.find(d=>d.name==='p1-host');if(pilot)$('historyDevice').value=pilot.id;schedule=await api('/schedule');$('enabled').checked=schedule.enabled;$('dailyTime').value=schedule.time;$('timezone').value=schedule.timezone;$('scheduleAll').checked=!schedule.devices.length;if(schedule.devices.length)document.querySelectorAll('#devices input').forEach(e=>e.checked=schedule.devices.includes(e.value));await Promise.all([deviceChanged(),loadAudit()]);translate()});
</script></body></html>'''
